$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot

$apiPath = Join-Path $root "app\api\brain\market-advice\[id]\route.ts"
$pagePath = Join-Path $root "app\assistant\market\[id]\page.tsx"
$offersPath = Join-Path $root "app\api\market\requests\[id]\offers\route.ts"

foreach ($path in @($apiPath, $pagePath, $offersPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Fichier introuvable : $path"
    }
}

$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    [System.Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($Value)
    )
}

$api = Decode ""
$offerOld = Decode "ICBpc1JlY29tbWVuZGVkOiBib29sZWFuOwogIGlzQ2hlYXBlc3Q6IGJvb2xlYW47Cn07"
$offerNew = Decode "ICBpc1JlY29tbWVuZGVkOiBib29sZWFuOwogIGlzQ2hlYXBlc3Q6IGJvb2xlYW47CiAgY292ZXJhZ2U6IHsKICAgIGNvdW50OiBudW1iZXI7CiAgICB0b3RhbDogbnVtYmVyOwogICAgZnVsbENvdmVyYWdlOiBib29sZWFuOwogICAgbGFiZWw6IHN0cmluZzsKICB9Owp9Ow=="
$requestOld = Decode "ICAgIGJ1ZGdldE1heDogbnVtYmVyIHwgbnVsbDsKICAgIHN0YXR1czogc3RyaW5nOwogIH07"
$requestNew = Decode ""
$statusOld = Decode "ICAgICAgICA8TWFya2V0U3RhdHVzVHJhY2tlciByZXF1ZXN0SWQ9e3BhcmFtcy5pZH0gLz4="
$statusNew = Decode ""
$verifyOld = Decode "ICAgICAgICAgICAgICAgICAgICAgICAge29mZmVyLnN0YXRzLmlzVmVyaWZpZWQgJiYgKA=="
$verifyNew = Decode ""
$buttonOld = Decode ""
$buttonNew = Decode ""
$selectOld = Decode "ICAgICAgICAiaWQsIGNsaWVudF9wcm9maWxlX2lkLCBzZXJ2aWNlX2lkLCB0aXRsZSwgZGVzY3JpcHRpb24sIHJlcXVlc3RlZF9kYXRlLCByZXF1ZXN0ZWRfdGltZSwgc3RhdHVzLCBhY2NlcHRlZF9vZmZlcl9pZCI="
$selectNew = Decode "ICAgICAgICAiaWQsIGNsaWVudF9wcm9maWxlX2lkLCBzZXJ2aWNlX2lkLCB0aXRsZSwgZGVzY3JpcHRpb24sIHJlcXVlc3RlZF9kYXRlLCByZXF1ZXN0ZWRfdGltZSwgcmVxdWVzdF9tb2RlLCBzdGF0dXMsIGFjY2VwdGVkX29mZmVyX2lkIg=="
$guardOld = Decode "ICAgIGNvbnN0IHsKICAgICAgZGF0YTogZXhpc3RpbmdRdW90ZSwKICAgICAgZXJyb3I6IGV4aXN0aW5nUXVvdGVFcnJvciwKICAgIH0gPSBhd2FpdCBzdXBhYmFzZUFkbWlu"
$guardNew = Decode ""

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($apiPath, $pagePath, $offersPath)) {
    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-84-" + $timestamp) -Force
}

# Complete API rewrite
[System.IO.File]::WriteAllText($apiPath, $api, $utf8)

# UI patches
$page = [System.IO.File]::ReadAllText($pagePath)

if (-not $page.Contains("KLYX_MULTI_SLOT_ADVICE_UI_12_84")) {
    foreach ($pair in @(
        @($offerOld, $offerNew),
        @($requestOld, $requestNew),
        @($statusOld, $statusNew),
        @($verifyOld, $verifyNew),
        @($buttonOld, $buttonNew)
    )) {
        if (-not $page.Contains($pair[0])) {
            throw "12.84 : ancre UI introuvable."
        }

        $page = $page.Replace($pair[0], $pair[1])
    }
}

[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

# Server-side mono-slot acceptance guard
$offers = [System.IO.File]::ReadAllText($offersPath)

if (-not $offers.Contains("KLYX_MULTI_SLOT_ACCEPT_GUARD_12_84")) {
    if (-not $offers.Contains($selectOld)) {
        throw "12.84 : select serviceRequest introuvable."
    }

    $offers = $offers.Replace($selectOld, $selectNew)

    if (-not $offers.Contains($guardOld)) {
        throw "12.84 : ancre existingQuote introuvable."
    }

    $offers = $offers.Replace($guardOld, $guardNew)
}

[System.IO.File]::WriteAllText($offersPath, $offers, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.84 APPLIQUE"
Write-Host "======================================"
Write-Host "Comparaison couverture : OK"
Write-Host "Priorite 100% creneaux : OK"
Write-Host "Resume multi-creneaux : OK"
Write-Host "Ancien booking mono bloque : OK"
Write-Host ""
